import { Component, Element, Host, Prop, Watch, h } from "@stencil/core";
const BUTTON_CHILDREN = ["hbr-button", "hbr-radio-button"] as const;
const BUTTON_SELECTOR = BUTTON_CHILDREN.join(",");
const SPLIT_BUTTON_ATTRIBUTE = "split-button";

type ButtonChildElement = HTMLHbrButtonElement | HTMLHbrRadioButtonElement;
type SplitButtonElement = HTMLHbrButtonElement | HTMLHbrDropdownElement;

/**
 * @since 0.0.10
 * @status stable
 *
 * @slot - One or more `<hbr-button>` elements to display in the button group.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-button-group",
	styleUrl: "button-group.scss",
	shadow: true,
})
export class ButtonGroup {
	buttonGroup?: HTMLElement;

	@Element() el!: HTMLHbrButtonGroupElement;

	/** A label to use for the button group's `aria-label` attribute. Deprecate candidate. Use 'aria' prop instead. */
	@Prop() label = "";

	/** Attributes related to screen readers. */
	@Prop() aria?: { label?: string };

	/** sizes */
	@Prop({ reflect: true }) size?: "small" | "medium" | "large";

	/** The button group's disabled state. */
	@Prop({ reflect: true }) disabled = false;

	/** The button's color scheme. */
	@Prop({ reflect: true }) sentiment?:
		| "neutral"
		| "interact"
		| "admin"
		| "success"
		| "warning"
		| "danger"
		| "info";

	@Prop({ mutable: true }) disableRole = false;

	@Watch("disabled")
	handleDisabledChange(newValue: boolean) {
		const slottedElements = this.getSlottedElements();

		slottedElements.forEach((el) => {
			const button = findButton(el);
			if (button !== null) {
				button.disabled = newValue;
			}
		});
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleMouseOver = this.handleMouseOver.bind(this);
		this.handleMouseOut = this.handleMouseOut.bind(this);
	}

	private getSlottedElements() {
		const slot = this.el.shadowRoot?.querySelector("slot");
		if (!(slot instanceof HTMLSlotElement)) {
			return [];
		}

		return slot
			.assignedElements({ flatten: true })
			.filter((el): el is HTMLElement => {
				return el instanceof HTMLElement;
			});
	}

	private getButtonFromEventTarget(target: EventTarget | null) {
		if (!(target instanceof HTMLElement)) {
			return null;
		}

		return findButton(target);
	}

	private getIsSplitButton(slottedElements: HTMLElement[]) {
		if (slottedElements.length !== 2) {
			return false;
		}

		const [firstElement, secondElement] = slottedElements;
		if (!isButtonElement(firstElement)) {
			return false;
		}

		if (isDropdownElement(secondElement)) {
			return hasLightDomTriggerButton(secondElement);
		}

		return (
			isButtonElement(secondElement) &&
			this.isAnchoredByExternalDropdown(secondElement)
		);
	}

	private resolveDropdownAnchor(dropdown: HTMLHbrDropdownElement) {
		const anchor = dropdown.anchor ?? dropdown.getAttribute("anchor");
		if (typeof anchor === "string") {
			try {
				return this.el.ownerDocument.querySelector(anchor);
			} catch {
				return null;
			}
		}

		return anchor instanceof HTMLElement ? anchor : null;
	}

	private isAnchoredByExternalDropdown(button: HTMLHbrButtonElement) {
		const dropdowns =
			this.el.ownerDocument.querySelectorAll<HTMLHbrDropdownElement>(
				"hbr-dropdown",
			);

		return Array.from(dropdowns).some((dropdown) => {
			return this.resolveDropdownAnchor(dropdown) === button;
		});
	}

	private setSplitButtonAttribute(value: boolean) {
		this.el.toggleAttribute(SPLIT_BUTTON_ATTRIBUTE, value);
	}

	handleFocus(event: FocusEvent) {
		if (this.disabled) return;
		const button = this.getButtonFromEventTarget(event.target);
		button?.classList.add("hbr-button-group__button--focus");
	}

	handleBlur(event: FocusEvent) {
		const button = this.getButtonFromEventTarget(event.target);
		button?.classList.remove("hbr-button-group__button--focus");
	}

	handleMouseOver(event: MouseEvent) {
		if (this.disabled) return;
		const button = this.getButtonFromEventTarget(event.target);
		button?.classList.add("hbr-button-group__button--hover");
	}

	handleMouseOut(event: MouseEvent) {
		const button = this.getButtonFromEventTarget(event.target);
		button?.classList.remove("hbr-button-group__button--hover");
	}

	handleSlotChange() {
		const slottedElements = this.getSlottedElements();
		const splitButton = this.getIsSplitButton(slottedElements);
		this.setSplitButtonAttribute(splitButton);

		slottedElements.forEach((el, index) => {
			const button = findButton(el);
			const sentiment = this.sentiment;

			/** set/overwrite sentiment on split button */
			if (splitButton) {
				const buttonElement = getSplitButtonElement(el, index);
				if (buttonElement) {
					const triggerEl = isDropdownElement(buttonElement)
						? buttonElement.querySelector("hbr-button[slot='trigger']") ||
						  buttonElement.querySelector("hbr-button")
						: null;
					const trigger = isButtonElement(triggerEl) ? triggerEl : null;

					if (!sentiment) {
						if (!buttonElement.sentiment) {
							buttonElement.sentiment = "interact";

							if (trigger && !trigger.sentiment) {
								trigger.sentiment = "interact";
							}
						}
					} else {
						buttonElement.sentiment = sentiment;
						if (trigger) {
							trigger.sentiment = sentiment;
						}
					}
				}
			}
			/** ------------------------------- */

			if (button !== null) {
				const isSplitMember = splitButton && index < 2;
				const splitPosition = isSplitMember
					? index === 0
						? "left"
						: "right"
					: null;

				button.classList.add("hbr-button-group__button");
				button.classList.toggle("button--split", isSplitMember);
				button.classList.toggle("hbr-button-group__button--first", index === 0);
				button.classList.toggle(
					"hbr-button-group__button--inner",
					index > 0 && index < slottedElements.length - 1,
				);
				button.classList.toggle(
					"hbr-button-group__button--last",
					index === slottedElements.length - 1,
				);
				button.classList.toggle(
					"hbr-button-group__button--radio",
					button.localName === "hbr-radio-button",
				);
				if (isButtonElement(button)) {
					void button.setSplitPosition(splitPosition ?? undefined);
				}
				if (this.disabled) {
					button.disabled = true;
				}
			}
		});
	}

	render() {
		return (
			<Host>
				<div
					ref={(el) => {
						this.buttonGroup = el;
					}}
					part="base"
					class={{
						"button-group": true,
						"button-group--disabled": this.disabled,
						[`button-group--${this.size}`]: !!this.size,
						[`button-group--${this.sentiment}`]: !!this.sentiment,
					}}
					role={this.disableRole ? "presentation" : "group"}
					aria-label={this.aria?.label || this.label}
					aria-disabled={this.disabled}
					onMouseOver={this.handleMouseOver}
					onBlur={this.handleBlur}
					onFocus={this.handleFocus}
					onMouseOut={this.handleMouseOut}
				>
					<slot onSlotchange={this.handleSlotChange} />
				</div>
			</Host>
		);
	}
}

function isButtonElement(el: Element | null): el is HTMLHbrButtonElement {
	return !!el && el.localName === "hbr-button";
}

function isDropdownElement(el: Element | null): el is HTMLHbrDropdownElement {
	return !!el && el.localName === "hbr-dropdown";
}

function hasLightDomTriggerButton(dropdown: HTMLHbrDropdownElement) {
	return Array.from(dropdown.children).some((child) => {
		return (
			isButtonElement(child) &&
			(!child.hasAttribute("slot") || child.slot === "trigger")
		);
	});
}

function isButtonChildElement(el: Element | null): el is ButtonChildElement {
	return (
		!!el &&
		BUTTON_CHILDREN.includes(el.localName as (typeof BUTTON_CHILDREN)[number])
	);
}

function getSplitButtonElement(
	el: HTMLElement,
	index: number,
): SplitButtonElement | null {
	if (index === 0 && isButtonElement(el)) {
		return el;
	}

	if (index === 1 && (isDropdownElement(el) || isButtonElement(el))) {
		return el;
	}

	return null;
}

function findButton(el: HTMLElement): ButtonChildElement | null {
	if (isButtonChildElement(el)) {
		return el;
	}

	const button = el.querySelector(BUTTON_SELECTOR);
	return isButtonChildElement(button) ? button : null;
}
